  t["Demostración directa"] = "Direct proof";
  t["Demostración directa, por contrarrecíproco y por reducción al absurdo"] = "Direct proof, by contraposition and by contradiction";
  t["Demostrar por inducción que $1 + 2 + \\dots + n = \\frac{n(n+1)}{2}$ para todo natural $n \\ge 1$."] = "Prove by induction that $1 + 2 + \\dots + n = \\frac{n(n+1)}{2}$ for every natural $n \\ge 1$.";
  t["Demostrar por inducción que $1 + 3 + 5 + \\dots + (2n - 1) = n^2$."] = "Prove by induction that $1 + 3 + 5 + \\dots + (2n - 1) = n^2$.";
  t["Demostrar por inducción que $2^n > n$ para todo natural $n \\ge 1$."] = "Prove by induction that $2^n > n$ for every natural $n \\ge 1$.";
  t["Demostrar por inducción que $A^n = \\begin{pmatrix} 1 & n \\\\ 0 & 1 \\end{pmatrix}$ para $A = \\begin{pmatrix} 1 & 1 \\\\ 0 & 1 \\end{pmatrix}$."] = "Prove by induction that $A^n = \\begin{pmatrix} 1 & n \\\\ 0 & 1 \\end{pmatrix}$ for $A = \\begin{pmatrix} 1 & 1 \\\\ 0 & 1 \\end{pmatrix}$.";
  t["Demostrar que $1+2+\\dots+n = \\frac{n(n+1)}{2}$ para todo $n$"] = "Prove that $1+2+\\dots+n = \\frac{n(n+1)}{2}$ for every $n$";
  t["Demostrar que $2^n > n$ para todo natural $n$"] = "Prove that $2^n > n$ for every natural $n$";
  t["Demostrar que $\\sqrt{2}$ no es ninguna fracción de enteros."] = "Prove that $\\sqrt{2}$ is not a fraction of integers.";
  t["Demostrar que $\\sqrt{3}$ es irracional"] = "Prove that $\\sqrt{3}$ is irrational";
  t["Demostrar que hay infinitos números primos"] = "Prove that there are infinitely many primes";
  t["Demostrar que si $n$ es par, $n^2$ también lo es"] = "Prove that if $n$ is even, $n^2$ is even too";
  t["Demostrar que si $n^2$ es impar, $n$ es impar"] = "Prove that if $n^2$ is odd, $n$ is odd";
  t["Denominador"] = "Denominator";
  t["Denominador común: $"] = "Common denominator: $";
  t["Denominador común: $\\operatorname{mcm}("] = "Common denominator: $\\operatorname{lcm}(";
  t["Denominador común: $\\operatorname{mcm}(6, 4) = 12$, porque $6 = 2\\cdot 3$ y $4 = 2^2$, y se toman todos los primos con el mayor exponente: $2^2\\cdot 3$."] = "Common denominator: $\\operatorname{lcm}(6, 4) = 12$, because $6 = 2\\cdot 3$ and $4 = 2^2$, and you take all the primes with the largest exponent: $2^2\\cdot 3$.";
  t["Denominador: $"] = "Denominator: $";
